"""qcheck.py <yaml-file>... — for every rule_id in the file(s), test whether the `quote` field
appears character-exact in the cited transcript, and where. Prints EXACT@Lnnn / WRAP@Lnnn / MISS.
"""
import re
import sys
from pathlib import Path

import yaml

DIARY = Path("/home/user/BookMinder/claude-dev-log-diary")
LOC = re.compile(r"day-(\d{3})[a-z0-9-]*:L(\d+)")


def norm(s):
    return re.sub(r"\s+", " ", s).strip()


def main(files):
    for fp in files:
        doc = yaml.safe_load(Path(fp).read_text(errors="replace"))
        for section in ("skill_rules", "pairing_gems", "failure_modes"):
            for item in doc.get(section) or []:
                if not isinstance(item, dict):
                    continue
                rid = item.get("rule_id") or item.get("gem_id") or item.get("id") or item.get("loc")
                q = item.get("quote")
                ev = str(item.get("evidence") or item.get("loc") or "")
                if not q:
                    continue
                m = LOC.search(ev)
                if not m:
                    print(f"{rid}\tNO-LOC\t{ev[:60]}")
                    continue
                day, line = m.group(1), int(m.group(2))
                dayf = DIARY / f"day-{day}.md"
                if not dayf.exists():
                    print(f"{rid}\tNO-FILE")
                    continue
                lines = dayf.read_text(errors="replace").splitlines()
                nq = norm(q)
                hits = []
                for i in range(len(lines)):
                    if norm(lines[i]).find(nq) >= 0:
                        hits.append((i + 1, "single"))
                    elif i + 1 < len(lines) and norm(" ".join(lines[i:i + 3])).find(nq) >= 0:
                        hits.append((i + 1, "wrap"))
                near = [h for h in hits if abs(h[0] - line) <= 400]
                status = "MISS"
                if near:
                    status = f"{near[0][1].upper()}@L{near[0][0]}(cited L{line},d{abs(near[0][0]-line)})"
                elif hits:
                    status = f"FAR@{hits[0][0]} (cited L{line})"
                print(f"{rid}\t{status}\t{fp.split('/')[-1]}")


main(sys.argv[1:])

#!/usr/bin/env python3
"""qcheck2.py <yaml-file>... — locate each `quote` in its cited transcript; report START line and
whether the whole quote matched (EXACT) or only a prefix (PARTIAL-n chars of m).
"""
import re
import sys
from pathlib import Path

import yaml

DIARY = Path("/home/user/BookMinder/claude-dev-log-diary")
LOC = re.compile(r"day-(\d{3})[a-z0-9-]*:L(\d+)")


def norm(s):
    return re.sub(r"\s+", " ", s).strip()


def locate(lines, nq, span=12):
    """Return (startline, matched_chars) best match."""
    best = (None, 0)
    for i in range(len(lines)):
        joined = norm(" ".join(lines[i:i + span]))
        if not joined:
            continue
        # longest prefix of nq that this window starts-with-or-contains at position 0 of a line
        lo, hi = 0, len(nq)
        # binary search longest prefix contained
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if nq[:mid] in joined:
                lo = mid
            else:
                hi = mid - 1
        if lo > best[1]:
            # require the match to begin within the first line of the window
            first = norm(lines[i])
            if lo >= 12 and nq[:min(lo, 12)] in first or lo == len(nq) and nq in first:
                best = (i + 1, lo)
            elif lo > best[1] and nq[:12] in first:
                best = (i + 1, lo)
    return best


def main(files):
    for fp in files:
        doc = yaml.safe_load(Path(fp).read_text(errors="replace"))
        for section in ("skill_rules", "pairing_rules", "pairing_gems", "failure_modes", "anti_patterns", "council_episodes"):
            for item in doc.get(section) or []:
                if not isinstance(item, dict):
                    continue
                rid = item.get("rule_id") or item.get("gem_id") or item.get("id") or item.get("name") or item.get("loc")
                q = item.get("quote")
                ev = str(item.get("evidence") or item.get("loc") or "")
                if not q:
                    continue
                m = LOC.search(ev)
                if not m:
                    print(f"{rid}\tNO-LOC\t{ev[:60]}")
                    continue
                day, line = m.group(1), int(m.group(2))
                dayf = DIARY / f"day-{day}.md"
                lines = dayf.read_text(errors="replace").splitlines()
                nq = norm(q)
                start, matched = locate(lines, nq)
                tag = "EXACT" if matched == len(nq) else f"PARTIAL {matched}/{len(nq)}"
                d = "" if start is None else f" (cited L{line}, d{start - line:+d})"
                print(f"{rid}\t{tag}\tstart=L{start}{d}\t{fp.split('/')[-1]}")


main(sys.argv[1:])

#!/usr/bin/env python3
"""qcheck3.py <yaml-file>... — locate each `quote` in its cited transcript (fast)."""
import re
import sys
from pathlib import Path

import yaml

DIARY = Path("/home/user/BookMinder/claude-dev-log-diary")
LOC = re.compile(r"day-(\d{3})[a-z0-9-]*:L(\d+)")
CACHE = {}


def norm(s):
    return re.sub(r"\s+", " ", s).strip()


def get(day):
    if day not in CACHE:
        lines = (DIARY / f"day-{day}.md").read_text(errors="replace").splitlines()
        CACHE[day] = (lines, [norm(x) for x in lines])
    return CACHE[day]


def locate(lines, nlines, nq, span=14):
    head = nq[:18]
    best = (None, 0)
    for i, nl in enumerate(nlines):
        if head not in nl:
            continue
        joined = norm(" ".join(lines[i:i + span]))
        pos = joined.find(head)
        lo, hi = 0, len(nq)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            lo, hi = (mid, hi) if joined.find(nq[:mid], pos) == pos else (lo, mid - 1)
        if lo > best[1]:
            best = (i + 1, lo)
    return best


def main(files):
    for fp in files:
        doc = yaml.safe_load(Path(fp).read_text(errors="replace"))
        for section in ("skill_rules", "pairing_rules", "pairing_gems", "failure_modes", "anti_patterns", "council_episodes"):
            for item in doc.get(section) or []:
                if not isinstance(item, dict):
                    continue
                rid = item.get("rule_id") or item.get("gem_id") or item.get("id") or item.get("name") or item.get("loc")
                q = item.get("quote")
                ev = str(item.get("evidence") or item.get("loc") or "")
                if not q:
                    continue
                m = LOC.search(ev)
                if not m:
                    print(f"{rid}\tNO-LOC\t{ev[:60]}\t{fp.split('/')[-1]}")
                    continue
                day, line = m.group(1), int(m.group(2))
                lines, nlines = get(day)
                nq = norm(q)
                start, matched = locate(lines, nlines, nq)
                tag = "EXACT" if matched == len(nq) else f"PARTIAL {matched}/{len(nq)}"
                d = "" if start is None else f" (cited L{line}, d{start - line:+d})"
                print(f"{rid}\t{tag}\tstart=L{start}{d}\t{fp.split('/')[-1]}")


main(sys.argv[1:])

